Igen — ezt meg lehet csinálni egy egyszerű webappként. A folyamat:

1. Szöveg → UTF8 bájtok  
2. Minden bájt értékét megszorozza 0805tel, azaz 805tel  
3. Az eredményeket eltárolja bináris formában  
4. Base64ként kiadja  
5. Dekódoláskor Base64 → számok → osztás 805tel → eredeti szöveg

Fontos: ez nem titkosítás, csak egy könnyen visszafejthető, saját kódolási eljárás. A Base64 eleve nem védelmi megoldás.

html
<!doctype html>
<html lang="hu">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Base64 × 805 Encoder / Decoder</title>
  <style>
    body {
      max-width: 800px;
      margin: 40px auto;
      padding: 0 16px;
      background: #111827;
      color: #f9fafb;
      font-family: Arial, sans-serif;
    }

    textarea {
      width: 100%;
      min-height: 130px;
      box-sizing: border-box;
      margin: 12px 0;
      padding: 12px;
      border: 1px solid #374151;
      border-radius: 8px;
      background: #1f2937;
      color: #fff;
      resize: vertical;
    }

    button {
      padding: 10px 16px;
      margin: 4px 6px 14px 0;
      border: 0;
      border-radius: 7px;
      background: #2563eb;
      color: #fff;
      font-weight: bold;
      cursor: pointer;
    }

    button:hover {
      background: #1d4ed8;
    }

    .error {
      color: #fca5a5;
      min-height: 22px;
    }

    code {
      color: #93c5fd;
    }
  </style>
</head>
<body>
  <h1>Szöveg → Base64 × 805</h1>

  <p>
    A szöveg minden UTF-8 bájtját megszorozza
    <code>805</code>-tel, majd Base64 formátumban adja vissza.
  </p>

  <textarea id="input" placeholder="Írd ide a szöveget vagy a kódolt Base64 értéket..."></textarea>

  <button onclick="encodeText()">Kódolás</button>
  <button onclick="decodeText()">Dekódolás</button>
  <button onclick="copyOutput()">Kimenet másolása</button>

  <textarea id="output" readonly placeholder="Itt jelenik meg az eredmény..."></textarea>
  <div id="error" class="error"></div>

  <script>
    const MULTIPLIER = 805;

    function encodeText() {
      const input = document.getElementById("input").value;
      const output = document.getElementById("output");
      const error = document.getElementById("error");

      error.textContent = "";

      try {
        const bytes = new TextEncoder().encode(input);

        // Egy eredeti bájt × 805 maximuma: 255 × 805 = 205275
        // Ez 4 bájton biztonságosan tárolható.
        const buffer = new ArrayBuffer(bytes.length * 4);
        const view = new DataView(buffer);

        bytes.forEach((byte, index) => {
          view.setUint32(index * 4, byte * MULTIPLIER, false);
        });

        const encodedBytes = new Uint8Array(buffer);
        let binary = "";

        encodedBytes.forEach(byte => {
          binary += String.fromCharCode(byte);
        });

        output.value = btoa(binary);
      } catch (err) {
        error.textContent = "Kódolási hiba: " + err.message;
      }
    }

    function decodeText() {
      const input = document.getElementById("input").value.trim();
      const output = document.getElementById("output");
      const error = document.getElementById("error");

      error.textContent = "";

      try {
        const binary = atob(input);
        const encodedBytes = Uint8Array.from(binary, char => char.charCodeAt(0));

        if (encodedBytes.length % 4 !== 0) {
          throw new Error("Érvénytelen kódolt adat.");
        }

        const view = new DataView(encodedBytes.buffer);
        const originalBytes = [];

        for (let i = 0; i < encodedBytes.length; i += 4) {
          const multipliedValue = view.getUint32(i, false);

          if (multipliedValue % MULTIPLIER !== 0) {
            throw new Error("Ez az érték nem ezzel a 805-ös módszerrel lett kódolva.");
          }

          const originalValue = multipliedValue / MULTIPLIER;

          if (originalValue < 0 || originalValue > 255) {
            throw new Error("Érvénytelen dekódolt bájtérték.");
          }

          originalBytes.push(originalValue);
        }

        output.value = new TextDecoder().decode(new Uint8Array(originalBytes));
      } catch (err) {
        error.textContent = "Dekódolási hiba: " + err.message;
      }
    }

    async function copyOutput() {
      const text = document.getElementById("output").value;

      if (!text) return;

      await navigator.clipboard.writeText(text);
      document.getElementById("error").textContent = "A kimenet a vágólapra került.";
    }
  </script>
</body>
</html>


Mentsd el például base64-805.html néven, majd nyisd meg böngészőben.

Példa: az A karakter UTF8 értéke 65. Kódoláskor \(65 \times 805 = 52325\), ezt tárolja a program, majd Base64re alakítja. Visszafejtéskor a 52325öt elosztja 805tel, így újra 65, vagyis A lesz.

